const WORKFLOW_EXECUTION_PATH = "/pipeline/executions/";

export function buildWorkflowExecutionUrl(
	workflowName: string,
	runId?: string,
	options?: { parentRunId?: string; pathName?: string },
): string {
	const trimmedRunId = runId?.trim();
	const trimmedParentRunId = options?.parentRunId?.trim();
	const encodedName = encodeURIComponent(
		options?.pathName?.trim() || workflowName,
	);
	if (!trimmedRunId && !trimmedParentRunId) {
		return `${WORKFLOW_EXECUTION_PATH}${encodedName}`;
	}
	const params = new URLSearchParams();
	if (trimmedRunId) params.set("runId", trimmedRunId);
	if (trimmedParentRunId) params.set("parentRunId", trimmedParentRunId);
	return `${WORKFLOW_EXECUTION_PATH}${encodedName}?${params.toString()}`;
}
